    re.compile(r'discount\s*code\s*[:\-]?\s*([A-Za-z0-9\-]{4,30})', re.I),
    re.compile(r'coupon\s*code\s*[:\-]?\s*([A-Za-z0-9\-]{4,30})', re.I),
    re.compile(r'use\s*(?:your\s*)?code\s*[:\-]?\s*([A-Za-z0-9\-]{4,30})', re.I),
    re.compile(r'redeem\s*(?:this\s*)?code\s*[:\-]?\s*([A-Za-z0-9\-]{4,30})', re.I),
    re.compile(r'enter\s*code\s*[:\-]?\s*([A-Za-z0-9\-]{4,30})', re.I),
    # Fallback: promo/discount/coupon/offer near a code-ish token
    re.compile(r'(?:promo|discount|coupon|offer)[^A-Za-z0-9]{0,25}([A-Za-z0-9\-]{4,30})', re.I),
]

codes_upper_to_original = {}

amazon_context_pat = re.compile(r'\bamazon\b', re.I)

for idx, tid in enumerate(thread_ids_all):
    if idx % 50 == 0:
        print('processing', idx, '/', len(thread_ids_all), 'thread_id', tid, 'codes_found', len(codes_upper_to_original))
    try:
        thread = apis.gmail.show_thread(email_thread_id=tid, access_token=gmail_token)
    except Exception as e:
        print('error_thread', tid, e)
        continue

    # Consider emails and drafts bodies
    texts = []
    for em in thread.get('emails', []) or []:
        body = em.get('body')
        if body:
            texts.append(body)
    for dr in thread.get('drafts', []) or []:
        body = dr.get('body')
        if body:
            texts.append(body)

    if not texts:
        continue

    # Only try extraction if Amazon context is present somewhere in the thread (reduces false codes)
    joined = '\n'.join(texts)
    if not amazon_context_pat.search(joined):
        continue

    for pat in code_res_patterns:
        for m in pat.findall(joined):
            code = m.strip()
            # Clean trailing punctuation
            code = re.sub(r'[\s\.,;:!\?]+$', '', code)
            if len(code) < 4:
                continue
            cu = code.upper()
            if cu not in codes_upper_to_original:
